import { test, expect } from '@playwright/test';

const FINGERPRINT_HEADER = { 'x-browser-fingerprint': 'qa-fp-search-spec-001' };

test.describe('Search Feature API Contracts', () => {
  test('GET /api/v1/search validates required query parameter q', async ({ request }) => {
    // Missing query parameter
    const missingRes = await request.get('/api/v1/search');
    expect(missingRes.status()).toBe(400);

    // Empty query parameter
    const emptyRes = await request.get('/api/v1/search', { params: { q: '' } });
    expect(emptyRes.status()).toBe(400);

    // Whitespace only query parameter
    const blankRes = await request.get('/api/v1/search', { params: { q: '   ' } });
    expect(blankRes.status()).toBe(400);
  });

  test('GET /api/v1/search finds posts by fuzzy keyword match', async ({ request }) => {
    const uniqueKeyword = `SearchTarget_${Date.now()}`;
    const postRes = await request.post('/api/v1/posts', {
      headers: FINGERPRINT_HEADER,
      data: { content: `Hello this is a post containing ${uniqueKeyword} for search verification.` },
    });
    expect([200, 201]).toContain(postRes.status());

    const searchRes = await request.get('/api/v1/search', {
      headers: FINGERPRINT_HEADER,
      params: { q: uniqueKeyword },
    });
    expect(searchRes.status()).toBe(200);
    const body = await searchRes.json();
    expect(body.query).toBe(uniqueKeyword);
    expect(Array.isArray(body.posts)).toBe(true);
    expect(body.posts.length).toBeGreaterThan(0);
    const matched = body.posts.find((p: any) => p.content.includes(uniqueKeyword));
    expect(matched).toBeDefined();
    expect(matched.username).toBeTruthy();
    expect(typeof matched.likes_count).toBe('number');
    expect(typeof matched.comments_count).toBe('number');
  });

  test('GET /api/v1/search finds users by @ prefix query', async ({ request }) => {
    const targetFp = `user-search-${Date.now()}`;
    await request.post('/api/v1/posts', {
      headers: { 'x-browser-fingerprint': targetFp },
      data: { content: `Seed post for user creation ${Date.now()}` },
    });

    const searchRes = await request.get('/api/v1/search', {
      headers: FINGERPRINT_HEADER,
      params: { q: `@${targetFp.substring(0, 10)}` },
    });
    expect(searchRes.status()).toBe(200);
    const body = await searchRes.json();
    expect(Array.isArray(body.users)).toBe(true);
    if (body.users.length > 0) {
      expect(body.users[0]).toHaveProperty('id');
      expect(body.users[0]).toHaveProperty('username');
    }
  });

  test('GET /api/v1/search respects type filtering (posts vs users)', async ({ request }) => {
    const keyword = `TypeFilter_${Date.now()}`;
    await request.post('/api/v1/posts', {
      headers: FINGERPRINT_HEADER,
      data: { content: `Post for type filter ${keyword}` },
    });

    // Filter type=posts
    const postsOnlyRes = await request.get('/api/v1/search', {
      headers: FINGERPRINT_HEADER,
      params: { q: keyword, type: 'posts' },
    });
    expect(postsOnlyRes.status()).toBe(200);
    const postsOnlyBody = await postsOnlyRes.json();
    expect(Array.isArray(postsOnlyBody.posts)).toBe(true);
    expect(postsOnlyBody.users).toEqual([]);

    // Filter type=users
    const usersOnlyRes = await request.get('/api/v1/search', {
      headers: FINGERPRINT_HEADER,
      params: { q: keyword, type: 'users' },
    });
    expect(usersOnlyRes.status()).toBe(200);
    const usersOnlyBody = await usersOnlyRes.json();
    expect(usersOnlyBody.posts).toEqual([]);
    expect(Array.isArray(usersOnlyBody.users)).toBe(true);
  });

  test('GET /api/v1/search returns empty arrays for non-matching query', async ({ request }) => {
    const nonExistent = `non_existent_search_keyword_${Date.now()}_xyz`;
    const searchRes = await request.get('/api/v1/search', {
      headers: FINGERPRINT_HEADER,
      params: { q: nonExistent },
    });
    expect(searchRes.status()).toBe(200);
    const body = await searchRes.json();
    expect(body.posts).toEqual([]);
    expect(body.users).toEqual([]);
  });
});

test.describe('Search Feature Web E2E', () => {
  test('User searches for post keyword in sidebar search box and views results', async ({ page, request }) => {
    const uniquePostText = `SearchableTweet_${Date.now()}`;
    await request.post('/api/v1/posts', {
      headers: FINGERPRINT_HEADER,
      data: { content: uniquePostText },
    });

    await page.goto('/');

    // Scoped locator according to RSI rule
    const searchInput = page
      .locator('.x-search-box')
      .locator('input.x-search-input')
      .or(page.locator('.x-sidebar-right').getByRole('textbox', { name: /搜索/i }))
      .first();

    await expect(searchInput).toBeVisible();
    await searchInput.fill(uniquePostText);
    await searchInput.press('Enter');

    // Scoped main container / search results container
    const mainContainer = page.getByRole('main').or(page.locator('.x-main-feed')).first();
    await expect(mainContainer.getByText(uniquePostText)).toBeVisible();
  });

  test('User searches with @ query to find users and triggers direct message', async ({ page, request }) => {
    const uniqueUserFp = `alice_test_${Date.now()}`;
    await request.post('/api/v1/posts', {
      headers: { 'x-browser-fingerprint': uniqueUserFp },
      data: { content: `Alice unique post ${Date.now()}` },
    });

    await page.goto('/');

    const searchInput = page
      .locator('.x-search-box')
      .locator('input.x-search-input')
      .or(page.locator('.x-sidebar-right').getByRole('textbox', { name: /搜索/i }))
      .first();

    await expect(searchInput).toBeVisible();
    await searchInput.fill(`@${uniqueUserFp}`);
    await searchInput.press('Enter');

    const mainContainer = page.getByRole('main').or(page.locator('.x-main-feed')).first();
    const userCard = mainContainer
      .locator('.user-card, .search-user-item, article, [data-testid="search-user"]')
      .filter({ hasText: uniqueUserFp })
      .or(mainContainer.getByText(uniqueUserFp))
      .first();
    await expect(userCard).toBeVisible();

    // Trigger direct message if DM button is present
    const dmButton = userCard
      .getByRole('button', { name: /私信|发消息|message|dm/i })
      .or(userCard.locator('button'))
      .first();
    if (await dmButton.isVisible()) {
      await dmButton.click();
      await expect(
        page.getByRole('heading', { name: /私信|站内信|messages/i })
          .or(page.getByLabel(/私信内容|消息内容|message/i))
          .or(page.locator('.messages-container'))
      ).toBeVisible();
    }
  });

  test('User sees friendly empty state when search finds no results', async ({ page }) => {
    await page.goto('/');

    const searchInput = page
      .locator('.x-search-box')
      .locator('input.x-search-input')
      .or(page.locator('.x-sidebar-right').getByRole('textbox', { name: /搜索/i }))
      .first();

    await expect(searchInput).toBeVisible();
    const nonExistent = `non_existent_term_${Date.now()}`;
    await searchInput.fill(nonExistent);
    await searchInput.press('Enter');

    const mainContainer = page.getByRole('main').or(page.locator('.x-main-feed')).first();
    await expect(
      mainContainer.getByText(/未找到|没有找到|暂无|无相关结果|no results/i)
    ).toBeVisible();
  });

  test('User can clear search and return to default feed stream', async ({ page, request }) => {
    const seedPost = `DefaultFeedItem_${Date.now()}`;
    await request.post('/api/v1/posts', {
      headers: FINGERPRINT_HEADER,
      data: { content: seedPost },
    });

    await page.goto('/');
    const searchInput = page
      .locator('.x-search-box')
      .locator('input.x-search-input')
      .or(page.locator('.x-sidebar-right').getByRole('textbox', { name: /搜索/i }))
      .first();

    await expect(searchInput).toBeVisible();
    await searchInput.fill('temp_search_query');
    await searchInput.press('Enter');

    // Either click a clear/back button or clear the search input and press Enter
    const backOrClearBtn = page
      .locator('.search-back-btn, .clear-search-btn')
      .or(page.getByRole('button', { name: /返回|清空|退出搜索|back|clear/i }))
      .first();

    if (await backOrClearBtn.isVisible()) {
      await backOrClearBtn.click();
    } else {
      await searchInput.fill('');
      await searchInput.press('Enter');
    }

    const mainContainer = page.getByRole('main').or(page.locator('.x-main-feed')).first();
    await expect(
      mainContainer.getByTestId('feed-list').or(mainContainer.locator('.post-card, article').first())
    ).toBeVisible();
  });
});
